// Tiny synthesized sound engine — no external audio assets.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.muted = false;
    this.started = false;
    this.noiseBuffer = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 18;
    comp.ratio.value = 5;
    comp.attack.value = 0.003;
    comp.release.value = 0.22;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);

    const len = Math.floor(this.ctx.sampleRate * 1.2);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const w = Math.random() * 2 - 1;
      last = 0.96 * last + 0.04 * w;
      data[i] = last * 2.6;
    }
    this.noiseBuffer = buf;
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(m ? 0 : 0.55, this.ctx.currentTime + 0.12);
    }
    if (this.musicGain) {
      this.musicGain.gain.linearRampToValueAtTime(m ? 0 : 0.11, this.ctx.currentTime + 0.3);
    }
  }

  get t() { return this.ctx ? this.ctx.currentTime : 0; }

  _tone({ f = 440, to = null, dur = 0.2, type = 'sine', vol = 0.2, delay = 0, attack = 0.005, dest = null }) {
    if (!this.ctx || this.muted) return;
    const t0 = this.t + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(f, t0);
    if (to !== null) o.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(vol, t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g);
    g.connect(dest || this.master);
    o.start(t0);
    o.stop(t0 + dur + 0.05);
  }

  _noise({ dur = 0.2, vol = 0.2, type = 'lowpass', f = 1000, q = 0.8, delay = 0, to = null }) {
    if (!this.ctx || this.muted || !this.noiseBuffer) return;
    const t0 = this.t + delay;
    const s = this.ctx.createBufferSource();
    s.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(f, t0);
    if (to !== null) filter.frequency.exponentialRampToValueAtTime(Math.max(40, to), t0 + dur);
    filter.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(vol, t0 + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    s.connect(filter); filter.connect(g); g.connect(this.master);
    s.start(t0); s.stop(t0 + dur + 0.04);
  }

  shoot() {
    this._tone({ f: 820 + Math.random() * 120, to: 340, dur: 0.13, type: 'triangle', vol: 0.07 });
    this._noise({ dur: 0.09, vol: 0.025, type: 'highpass', f: 1800 });
  }
  hit() {
    this._tone({ f: 150, to: 70, dur: 0.11, type: 'square', vol: 0.1 });
    this._noise({ dur: 0.08, vol: 0.08, f: 700 });
  }
  enemyDie() {
    this._tone({ f: 180, to: 42, dur: 0.36, type: 'sawtooth', vol: 0.11 });
    this._noise({ dur: 0.34, vol: 0.11, f: 900, to: 120 });
  }
  hurt() {
    this._tone({ f: 210, to: 58, dur: 0.4, type: 'sawtooth', vol: 0.2 });
    this._noise({ dur: 0.25, vol: 0.15, f: 500, to: 90 });
  }
  coin() {
    this._tone({ f: 1180, dur: 0.09, type: 'sine', vol: 0.12 });
    this._tone({ f: 1760, dur: 0.2, type: 'sine', vol: 0.1, delay: 0.07 });
  }
  heart() {
    [523, 659, 784].forEach((f, i) => this._tone({ f, dur: 0.22, type: 'sine', vol: 0.11, delay: i * 0.06 }));
  }
  item() {
    [392, 493, 587, 784].forEach((f, i) => this._tone({ f, dur: 0.7, type: 'triangle', vol: 0.09, delay: i * 0.1 }));
    this._tone({ f: 196, dur: 1.4, type: 'sine', vol: 0.08, delay: 0.1 });
  }
  bombPlace() {
    this._tone({ f: 320, to: 180, dur: 0.15, type: 'triangle', vol: 0.1 });
    this._noise({ dur: 0.12, vol: 0.04, f: 900 });
  }
  explosion() {
    this._noise({ dur: 0.7, vol: 0.32, f: 1100, to: 60 });
    this._tone({ f: 90, to: 28, dur: 0.6, type: 'sine', vol: 0.28 });
  }
  door() {
    this._noise({ dur: 0.5, vol: 0.1, f: 340, to: 90 });
    this._tone({ f: 70, to: 48, dur: 0.5, type: 'sine', vol: 0.12 });
  }
  clear() {
    [330, 415, 494, 660].forEach((f, i) => this._tone({ f, dur: 0.55, type: 'triangle', vol: 0.06, delay: i * 0.11 }));
  }
  bossRoar() {
    this._tone({ f: 74, to: 36, dur: 1.5, type: 'sawtooth', vol: 0.2 });
    this._noise({ dur: 1.3, vol: 0.16, f: 440, to: 70 });
  }
  bossHit() {
    this._tone({ f: 120, to: 55, dur: 0.18, type: 'square', vol: 0.09 });
  }
  tearBlock() {
    this._noise({ dur: 0.08, vol: 0.04, f: 2500 });
  }
  step() {
    this._noise({ dur: 0.06, vol: 0.018, f: 260, type: 'lowpass' });
  }
  ui() {
    this._tone({ f: 520, to: 640, dur: 0.08, type: 'triangle', vol: 0.05 });
  }
  victory() {
    [262, 330, 392, 523, 659, 784].forEach((f, i) =>
      this._tone({ f, dur: 1.5, type: 'triangle', vol: 0.07, delay: i * 0.18 }));
  }
  gameOver() {
    [220, 196, 165, 110].forEach((f, i) =>
      this._tone({ f, dur: 1.4, type: 'sawtooth', vol: 0.06, delay: i * 0.28 }));
  }

  startMusic() {
    if (!this.ctx || this.started) return;
    this.started = true;
    const t = this.t;
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = this.muted ? 0 : 0.11;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 420;
    this.musicGain.connect(this.master);
    filter.connect(this.musicGain);

    const droneFreqs = [55, 55.35, 82.4, 110.2];
    droneFreqs.forEach((f, i) => {
      const o = this.ctx.createOscillator();
      o.type = i % 2 ? 'sawtooth' : 'sine';
      o.frequency.value = f;
      const g = this.ctx.createGain();
      g.gain.value = i === 0 ? 0.16 : 0.06;
      o.connect(g); g.connect(filter);
      const lfo = this.ctx.createOscillator();
      lfo.frequency.value = 0.04 + i * 0.017;
      const lg = this.ctx.createGain();
      lg.gain.value = 0.035;
      lfo.connect(lg); lg.connect(g.gain);
      o.start(t); lfo.start(t);
    });

    const wind = this.ctx.createBufferSource();
    wind.buffer = this.noiseBuffer;
    wind.loop = true;
    const wf = this.ctx.createBiquadFilter();
    wf.type = 'lowpass';
    wf.frequency.value = 160;
    const wg = this.ctx.createGain();
    wg.gain.value = 0.05;
    wind.connect(wf); wf.connect(wg); wg.connect(this.musicGain);
    wind.start(t);

    // A distant, irregular music-box note.
    const bell = () => {
      if (!this.ctx || this.muted) return;
      const notes = [523.25, 587.33, 659.25, 783.99, 880];
      const f = notes[Math.floor(Math.random() * notes.length)];
      this._tone({ f, dur: 2.8, type: 'sine', vol: 0.018, attack: 0.4, dest: this.musicGain });
      this._tone({ f: f * 2.01, dur: 2.2, type: 'sine', vol: 0.007, attack: 0.5, dest: this.musicGain });
      setTimeout(bell, 5000 + Math.random() * 9000);
    };
    setTimeout(bell, 3500);
  }
}

import * as THREE from 'three';

export function rng(seed = 1234567) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function canvas(size) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return c;
}

function noiseOverlay(ctx, size, amount = 16, rand = Math.random) {
  const img = ctx.getImageData(0, 0, size, size);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rand() * 2 - 1) * amount;
    d[i] = Math.max(0, Math.min(255, d[i] + n));
    d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + n));
    d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + n));
  }
  ctx.putImageData(img, 0, 0);
}

function drawCracks(ctx, rand, size, count, color) {
  ctx.strokeStyle = color;
  ctx.lineCap = 'round';
  for (let i = 0; i < count; i++) {
    let x = rand() * size, y = rand() * size;
    ctx.beginPath();
    ctx.moveTo(x, y);
    const segs = 2 + Math.floor(rand() * 5);
    for (let s = 0; s < segs; s++) {
      x += (rand() - 0.5) * 46;
      y += (rand() - 0.5) * 46;
      ctx.lineTo(x, y);
    }
    ctx.lineWidth = 0.4 + rand() * 1.2;
    ctx.globalAlpha = 0.18 + rand() * 0.3;
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

function stain(ctx, rand, size, count, color) {
  for (let i = 0; i < count; i++) {
    const x = rand() * size, y = rand() * size, r = 8 + rand() * 60;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, color);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
}

export function makeFloorTexture(theme) {
  const size = 512;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const rand = rng(theme.seed || 991);
  ctx.fillStyle = theme.floorBase;
  ctx.fillRect(0, 0, size, size);

  const cols = 4, rows = 4, tw = size / cols, th = size / rows;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const px = x * tw, py = y * th;
      const v = 0.82 + rand() * 0.28;
      ctx.fillStyle = shade(theme.floorTile, v);
      ctx.fillRect(px + 2, py + 2, tw - 4, th - 4);
      // bevel
      ctx.fillStyle = 'rgba(255,255,255,.035)';
      ctx.fillRect(px + 3, py + 3, tw - 6, 3);
      ctx.fillStyle = 'rgba(0,0,0,.16)';
      ctx.fillRect(px + 3, py + th - 6, tw - 6, 3);
      // inset panel
      ctx.strokeStyle = 'rgba(0,0,0,.13)';
      ctx.lineWidth = 1;
      ctx.strokeRect(px + tw * 0.18, py + th * 0.18, tw * 0.64, th * 0.64);
      if (rand() < 0.3) {
        ctx.fillStyle = 'rgba(0,0,0,.09)';
        ctx.beginPath();
        ctx.ellipse(px + rand() * tw, py + rand() * th, 12 + rand() * 28, 5 + rand() * 14, rand() * 3, 0, 7);
        ctx.fill();
      }
    }
  }
  // grout lines
  ctx.strokeStyle = 'rgba(8,6,5,.55)';
  ctx.lineWidth = 3;
  for (let x = 0; x <= cols; x++) {
    ctx.beginPath(); ctx.moveTo(x * tw, 0); ctx.lineTo(x * tw, size); ctx.stroke();
  }
  for (let y = 0; y <= rows; y++) {
    ctx.beginPath(); ctx.moveTo(0, y * th); ctx.lineTo(size, y * th); ctx.stroke();
  }
  stain(ctx, rand, size, 8, theme.stain || 'rgba(15,8,5,.28)');
  drawCracks(ctx, rand, size, 16, 'rgba(6,4,3,.7)');
  noiseOverlay(ctx, size, 15, rand);

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = 4;
  return tex;
}

export function makeWallTexture(theme) {
  const size = 512;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const rand = rng((theme.seed || 442) + 7);
  ctx.fillStyle = theme.wallBase;
  ctx.fillRect(0, 0, size, size);
  const rows = 6, cols = 4;
  const bh = size / rows;
  for (let r = 0; r < rows; r++) {
    const offset = (r % 2) * (size / cols) * 0.5;
    for (let col = -1; col < cols + 1; col++) {
      const x = col * (size / cols) + offset;
      const y = r * bh;
      const bw = size / cols;
      const v = 0.84 + rand() * 0.26;
      ctx.fillStyle = shade(theme.wallTile, v);
      ctx.fillRect(x + 3, y + 3, bw - 6, bh - 6);
      ctx.fillStyle = 'rgba(255,255,255,.045)';
      ctx.fillRect(x + 3, y + 3, bw - 6, 3);
      ctx.fillStyle = 'rgba(0,0,0,.22)';
      ctx.fillRect(x + 3, y + bh - 7, bw - 6, 4);
      if (rand() < 0.16) {
        ctx.fillStyle = 'rgba(0,0,0,.22)';
        ctx.beginPath();
        ctx.arc(x + 10 + rand() * (bw - 20), y + 10 + rand() * (bh - 20), 2 + rand() * 7, 0, 7);
        ctx.fill();
      }
    }
  }
  // mortar
  ctx.strokeStyle = 'rgba(5,4,3,.65)';
  ctx.lineWidth = 4;
  for (let r = 0; r <= rows; r++) {
    ctx.beginPath(); ctx.moveTo(0, r * bh); ctx.lineTo(size, r * bh); ctx.stroke();
  }
  // moss / damp
  stain(ctx, rand, size, 5, theme.moss || 'rgba(40,52,28,.20)');
  stain(ctx, rand, size, 6, 'rgba(0,0,0,.22)');
  drawCracks(ctx, rand, size, 10, 'rgba(4,3,2,.8)');
  noiseOverlay(ctx, size, 18, rand);

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = 4;
  return tex;
}

function shade(hex, v) {
  const c = new THREE.Color(hex);
  c.multiplyScalar(v);
  return '#' + c.getHexString();
}

export function makeGlowTexture(color = '#9feaff') {
  const size = 128;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.12, color);
  g.addColorStop(0.4, color.replace(')', ',.35)').replace('rgb', 'rgba'));
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makeSoftShadowTexture() {
  const size = 128;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 2, 64, 64, 62);
  g.addColorStop(0, 'rgba(0,0,0,.7)');
  g.addColorStop(0.55, 'rgba(0,0,0,.3)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  return new THREE.CanvasTexture(c);
}

export function makeSplatTexture(seed = 1, color = '#4a0909') {
  const size = 128;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const rand = rng(seed);
  ctx.fillStyle = color;
  ctx.beginPath();
  const cx = 64, cy = 64;
  const pts = 14;
  for (let i = 0; i < pts; i++) {
    const a = (i / pts) * Math.PI * 2;
    const r = 16 + rand() * 25;
    const x = cx + Math.cos(a) * r, y = cy + Math.sin(a) * r * 0.9;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.globalAlpha = 0.7;
  ctx.fill();
  for (let i = 0; i < 12; i++) {
    const a = rand() * Math.PI * 2;
    const d = 20 + rand() * 38;
    ctx.beginPath();
    ctx.arc(cx + Math.cos(a) * d, cy + Math.sin(a) * d, 1 + rand() * 5, 0, 7);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makeRuneTexture() {
  const size = 256;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.translate(128, 128);
  ctx.strokeStyle = 'rgba(231,193,116,.9)';
  ctx.lineWidth = 2;
  ctx.globalAlpha = 0.8;
  for (let ring = 0; ring < 3; ring++) {
    ctx.beginPath();
    ctx.arc(0, 0, 35 + ring * 22, 0, Math.PI * 2);
    ctx.stroke();
  }
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * Math.PI * 2;
    ctx.save();
    ctx.rotate(a);
    ctx.translate(0, -80);
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(-5, 12); ctx.lineTo(5, 12); ctx.closePath();
    ctx.stroke();
    ctx.restore();
  }
  // central star
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    const r = i % 2 ? 17 : 36;
    const a = (i / 10) * Math.PI * 2 - Math.PI / 2;
    const x = Math.cos(a) * r, y = Math.sin(a) * r;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.stroke();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makeParticleTexture() {
  const size = 64;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.25, 'rgba(255,255,255,.8)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  return new THREE.CanvasTexture(c);
}

