import * as THREE from 'three';
import { Dungeon, DIRS, THEMES } from './dungeon.js';
import { Models } from './models.js';
import { AudioEngine } from './audio.js';
import { makeFloorTexture, makeWallTexture, makeGlowTexture, makeRuneTexture, makeParticleTexture, rng } from './textures.js';

const $ = (id) => document.getElementById(id);
const canvas = $('game-canvas');
const scene = new THREE.Scene();
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 100);
camera.position.set(0, 17.5, 15.5);
camera.lookAt(0, 0, 0);
scene.add(new THREE.HemisphereLight(0xc9c0ad, 0x160d0a, 1.05));
const keyLight = new THREE.DirectionalLight(0xffdfb3, 1.5);
keyLight.position.set(-5, 12, 7);
scene.add(keyLight);
const ambientLight = new THREE.AmbientLight(0x877b70, 0.45);
scene.add(ambientLight);
const raycaster = new THREE.Raycaster();
const floorPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
const pointerNdc = new THREE.Vector2();
const aimPoint = new THREE.Vector3(0, 0, 3);
const textures = {
  glowCyan: makeGlowTexture('#9feaff'), glowWarm: makeGlowTexture('#ffc06b'),
  glowRed: makeGlowTexture('#ff594d'), glowBlue: makeGlowTexture('#78a8ff'),
  rune: makeRuneTexture(), particles: makeParticleTexture()
};
const models = new Models(textures);
const audio = new AudioEngine();
const dungeon = new Dungeon(260415);
const clock = new THREE.Clock();
const ROOM_W = 18, ROOM_D = 13.5, WALL_H = 3.2;
const player = { hp: 6, maxHp: 6, coins: 0, bombs: 1, damage: 1, fireRate: 0.31, speed: 5.2, invuln: 0, shotTimer: 0, x: 0, z: 0 };
let playerMesh, currentRoom, floorGroup, enemyList = [], tears = [], enemyShots = [], pickups = [], bombs = [], effects = [];
let floorIndex = 0, runTime = 0, gameState = 'title', roomCount = 1, bannerTimer = 0, toastTimer = 0;
let fireHeld = false, touchMode = false, mapVisible = true, lastShotSound = 0;
const keys = new Set();
const moveInput = new THREE.Vector2();
const aimInput = new THREE.Vector2();
const touch = { moveId: null, aimId: null, moveCenter: null, aimCenter: null };
const ui = {};
for (const id of ['hud','title-screen','pause-screen','end-screen','loading','fade','crosshair','touch-ui','pause-stats','end-stats','end-title','end-kicker','end-message','floor-label','boss-bar','boss-name','boss-fill','hearts','coin-count','bomb-count','room-banner','room-banner-name','room-banner-sub','room-status','item-toast','item-toast-name','item-toast-desc','minimap','hurt-flash','white-flash','hint']) ui[id] = $(id);

function resize() {
  const w = window.innerWidth, h = window.innerHeight;
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.fov = w < 700 ? 48 : 42;
  camera.updateProjectionMatrix();
  touchMode = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
  ui['touch-ui'].classList.toggle('hidden', !touchMode || gameState !== 'playing');
  ui.crosshair.classList.toggle('hidden', touchMode || gameState !== 'playing');
}
window.addEventListener('resize', resize);
resize();

function showBanner(title, subtitle) {
  ui['room-banner-name'].textContent = title;
  ui['room-banner-sub'].textContent = subtitle;
  ui['room-banner'].classList.add('show');
  bannerTimer = 2.2;
}
function roomTitle(room) {
  if (room.type === 'start') return 'THE ENTRANCE';
  if (room.type === 'boss') return 'BOSS CHAMBER';
  if (room.type === 'treasure') return 'THE OFFERING';
  return 'THE CELLAR';
}
function addMesh(parent, geometry, material, x, y, z, sx = 1, sy = 1, sz = 1) {
  const m = new THREE.Mesh(geometry, material);
  m.position.set(x, y, z); m.scale.set(sx, sy, sz); parent.add(m); return m;
}
function clearGroup(group) {
  while (group.children.length) {
    const child = group.children.pop();
    if (child.parent) child.parent.remove(child);
  }
}
function disposeGroup(group) {
  group.traverse(o => {
    if (o.geometry && !o.userData.sharedGeo) o.geometry.dispose();
    if (o.material && !Array.isArray(o.material)) {
      if (o.material !== models.mat.skin && o.material !== models.mat.stone && o.material !== models.mat.stoneDark && o.material !== models.mat.gold && o.material !== models.mat.tear) o.material.dispose();
    }
  });
}
function clearRoom() {
  if (floorGroup) { scene.remove(floorGroup); disposeGroup(floorGroup); }
  floorGroup = new THREE.Group(); scene.add(floorGroup);
  enemyList = []; tears.forEach(t => scene.remove(t.mesh)); tears = [];
  enemyShots.forEach(t => scene.remove(t.mesh)); enemyShots = [];
  pickups.forEach(p => scene.remove(p.mesh)); pickups = [];
  bombs.forEach(b => scene.remove(b.mesh)); bombs = [];
  effects.forEach(e => scene.remove(e.mesh)); effects = [];
}

function makeRoomShell(room, theme) {
  const floorTex = makeFloorTexture(theme), wallTex = makeWallTexture(theme);
  floorTex.repeat.set(3, 2.3); wallTex.repeat.set(2, 1);
  const floorMat = new THREE.MeshStandardMaterial({ map: floorTex, color: 0xaaa49a, roughness: 0.98 });
  const wallMat = new THREE.MeshStandardMaterial({ map: wallTex, color: 0xaaa49a, roughness: 0.96 });
  const floor = addMesh(floorGroup, new THREE.PlaneGeometry(ROOM_W, ROOM_D), floorMat, 0, 0, 0);
  floor.rotation.x = -Math.PI / 2; floor.receiveShadow = true;
  const trimMat = new THREE.MeshStandardMaterial({ color: theme.rockColor, roughness: 0.9 });
  const addWall = (x, z, width, depth, height = WALL_H) => {
    const wall = addMesh(floorGroup, new THREE.BoxGeometry(width, height, depth), wallMat, x, height / 2, z);
    wall.castShadow = true; wall.receiveShadow = true;
    addMesh(floorGroup, new THREE.BoxGeometry(width + 0.06, 0.17, depth + 0.07), trimMat, x, height - 0.08, z);
  };
  const gap = 3.2, side = (ROOM_W - gap) / 2;
  for (const x of [-ROOM_W/2 + side/2, ROOM_W/2 - side/2]) {
    addWall(x, -ROOM_D/2, side, 0.65); addWall(x, ROOM_D/2, side, 0.65);
  }
  const endW = 0.65, endD = ROOM_D - gap;
  for (const z of [-ROOM_D/2 + endD/2, ROOM_D/2 - endD/2]) {
    addWall(-ROOM_W/2, z, endW, endD); addWall(ROOM_W/2, z, endW, endD);
  }
  // Heavy lintels frame the four exits, while sealed rooms get readable stone doors.
  for (const dir of ['N','S','E','W']) {
    if (!room.doors[dir]) {
      if (dir === 'N' || dir === 'S') addMesh(floorGroup, new THREE.BoxGeometry(gap, 2.8, 0.42), trimMat, 0, 1.4, dir === 'N' ? -ROOM_D/2 : ROOM_D/2);
      else addMesh(floorGroup, new THREE.BoxGeometry(0.42, 2.8, gap), trimMat, dir === 'W' ? -ROOM_W/2 : ROOM_W/2, 1.4, 0);
    } else if (dir === 'N' || dir === 'S') {
      addMesh(floorGroup, new THREE.BoxGeometry(gap + 0.3, 0.32, 0.85), trimMat, 0, WALL_H - 0.1, dir === 'N' ? -ROOM_D/2 : ROOM_D/2);
    } else {
      addMesh(floorGroup, new THREE.BoxGeometry(0.85, 0.32, gap + 0.3), trimMat, dir === 'W' ? -ROOM_W/2 : ROOM_W/2, WALL_H - 0.1, 0);
    }
  }
  const rune = new THREE.Mesh(new THREE.PlaneGeometry(ROOM_W - 2, ROOM_D - 2), new THREE.MeshBasicMaterial({ map: textures.rune, color: 0x614d39, transparent: true, opacity: room.type === 'boss' ? 0.12 : 0.07, depthWrite: false }));
  rune.rotation.x = -Math.PI / 2; rune.position.y = 0.018; floorGroup.add(rune);
  // Crates and pillars lend the rooms a hand-built silhouette.
  const rand = rng(room.seed + floorIndex * 111);
  for (let i = 0; i < 5; i++) {
    if (rand() > 0.48) continue;
    const x = (rand() - 0.5) * 11, z = (rand() - 0.5) * 7;
    if (Math.abs(x) < 2.2 && Math.abs(z) < 2) continue;
    const prop = rand() > 0.53 ? models.createRock(room.seed + i, theme) : models.createPillar(1.7 + rand());
    prop.position.set(x, 0, z); floorGroup.add(prop);
  }
  // Warm torches at corners.
  for (const x of [-8, 8]) for (const z of [-5.7, 5.7]) {
    const torch = models.createCandle(0.8); torch.position.set(x, 0, z); floorGroup.add(torch);
    const light = new THREE.PointLight(theme.torch, 5, 7, 2); light.position.set(x, 2.1, z); floorGroup.add(light);
  }
  scene.fog = new THREE.FogExp2(theme.fog, theme.fogDensity * 0.42);
  ambientLight.color.setHex(theme.ambient); ambientLight.intensity = theme.ambientIntensity;
  keyLight.color.setHex(theme.directional); keyLight.intensity = theme.directionalIntensity;
}

function spawnEnemy(type, x, z, boss = false) {
  const theme = dungeon.theme;
  if (boss) { theme.bossColor = theme.boss.color; theme.bossGlow = theme.boss.glow; }
  const mesh = models.createEnemy(type, theme, Math.floor(Math.random() * 3));
  mesh.position.set(x, 0, z); mesh.castShadow = true; floorGroup.add(mesh);
  const hp = boss ? theme.boss.hp : type === 'fly' ? 22 : type === 'spitter' ? 36 : 40;
  enemyList.push({ mesh, type, hp, maxHp: hp, boss, cooldown: 0.7 + Math.random(), contact: boss ? theme.boss.contact : 1, phase: Math.random() * 6, hitFlash: 0 });
}
function spawnPickup(type, x, z) {
  const mesh = models.createPickup(type); mesh.position.set(x, 0, z); floorGroup.add(mesh);
  pickups.push({ mesh, type, x, z, phase: Math.random() * 6 });
}
function createRoom(room, enterDir = null) {
  clearRoom(); currentRoom = room; room.visited = room.discovered = room.entered = true;
  roomCount = [...dungeon.rooms.values()].filter(r => r.visited).length;
  makeRoomShell(room, dungeon.theme);
  if (playerMesh && playerMesh.parent) scene.remove(playerMesh);
  if (!playerMesh) { playerMesh = models.createPlayer(); scene.add(playerMesh); }
  player.x = 0; player.z = 0;
  if (enterDir === 'N') player.z = -5.3;
  if (enterDir === 'S') player.z = 5.3;
  if (enterDir === 'E') player.x = 7.6;
  if (enterDir === 'W') player.x = -7.6;
  playerMesh.position.set(player.x, 0, player.z);
  if (!room.cleared && room.type !== 'treasure') {
    if (room.type === 'boss') {
      spawnEnemy('boss', 0, -0.5, true);
      audio.bossRoar();
    } else {
      const rand = rng(room.seed + 741 + floorIndex * 980);
      const number = 2 + Math.floor(rand() * 3);
      for (let i = 0; i < number; i++) {
        const pool = dungeon.theme.enemyPool;
        const type = pool[Math.floor(rand() * pool.length)];
        let x = (rand() - 0.5) * 10, z = (rand() - 0.5) * 6;
        if (Math.hypot(x, z) < 3) x += x < 0 ? -3 : 3;
        spawnEnemy(type, x, z);
      }
    }
  }
  if (room.type === 'treasure' && !room.rewardTaken) {
    room.rewardTaken = true;
    const items = [
      { icon: 'ring', name: 'TEAR RING', desc: '+0.45 TEAR DAMAGE', apply: () => player.damage += 0.45 },
      { icon: 'hourglass', name: 'BROKEN HOURGLASS', desc: 'TEARS FLY FASTER', apply: () => player.fireRate = Math.max(0.13, player.fireRate * 0.78) },
      { icon: 'feather', name: 'MOTH WING', desc: 'MOVE FASTER', apply: () => player.speed += 0.7 },
      { icon: 'lens', name: 'WEEPING LENS', desc: 'TEARS HIT HARDER', apply: () => player.damage += 0.7 }
    ];
    room.item = items[Math.floor(Math.random() * items.length)];
    const pedestal = models.createPedestal(room.item); pedestal.position.set(0, 0, 0); floorGroup.add(pedestal);
    room.pedestal = pedestal;
  }
  if (room.type === 'boss' && room.cleared && !room.trapdoor) {
    room.trapdoor = models.createTrapdoor(true); room.trapdoor.position.set(0, 0.025, 0); floorGroup.add(room.trapdoor);
  }
  if (room.type === 'start' && !room.visitedGift) {
    room.visitedGift = true;
    spawnPickup('heart', -2.4, 1.8); spawnPickup('coin', 2.4, 1.8);
  }
  showBanner(roomTitle(room), `ROOM ${String(roomCount).padStart(2, '0')}  ·  ${dungeon.theme.name}`);
  ui['floor-label'].innerHTML = `${dungeon.theme.name} <span>${dungeon.theme.numeral}</span>`;
  ui['boss-bar'].classList.toggle('hidden', room.type !== 'boss' || room.cleared);
  ui['boss-name'].textContent = dungeon.theme.bossName;
  ui['room-status'].textContent = enemyList.length ? 'DOORS SEALED' : room.type === 'boss' && room.cleared ? 'DESCEND BELOW' : 'ROOM CLEARED';
  drawMap(); renderHud();
  audio.door();
}
function startRun() {
  audio.init(); audio.startMusic();
  player.hp = 6; player.maxHp = 6; player.coins = 0; player.bombs = 2; player.damage = 1; player.fireRate = 0.31; player.speed = 5.2; player.invuln = 0;
  floorIndex = 0; runTime = 0; roomCount = 1;
  dungeon.generateFloor(floorIndex);
  ui['title-screen'].classList.add('hidden'); ui['pause-screen'].classList.add('hidden'); ui['end-screen'].classList.add('hidden');
  ui.hud.classList.remove('hidden'); gameState = 'playing';
  resize(); createRoom(dungeon.start); renderHud();
}
function changeFloor() {
  if (floorIndex >= THEMES.length - 1) { endRun(true); return; }
  floorIndex++;
  ui.fade.classList.add('active');
  window.setTimeout(() => {
    dungeon.generateFloor(floorIndex);
    createRoom(dungeon.start);
    ui.fade.classList.remove('active'); showBanner(dungeon.theme.name, `FLOOR ${dungeon.theme.numeral} · DESCEND`);
  }, 450);
}

const itemInfo = {
  coin: ['COIN', '+1 COIN'], heart: ['HEART', '+1 HEART'], soul: ['SOUL HEART', '+1 SOUL HEART'], bomb: ['BOMB', '+1 BOMB']
};
function renderHud() {
  if (!ui.hearts) return;
  ui.hearts.replaceChildren();
  const full = Math.floor(player.hp / 2), half = player.hp % 2;
  for (let i = 0; i < Math.ceil(player.maxHp / 2); i++) {
    const heart = document.createElement('span'); heart.className = 'heart';
    heart.textContent = i < full ? '♥' : (i === full && half ? '♥' : '♡');
    if (i === full && half) heart.classList.add('half');
    ui.hearts.appendChild(heart);
  }
  ui['coin-count'].textContent = player.coins;
  ui['bomb-count'].textContent = player.bombs;
  if (currentRoom?.type === 'boss' && enemyList[0]?.boss) {
    ui['boss-bar'].classList.remove('hidden');
    ui['boss-fill'].style.width = `${Math.max(0, enemyList[0].hp / enemyList[0].maxHp * 100)}%`;
  }
}
function drawMap() {
  const c = ui.minimap, ctx = c.getContext('2d');
  ctx.clearRect(0, 0, c.width, c.height);
  ctx.fillStyle = 'rgba(7,6,6,.86)'; ctx.fillRect(0, 0, c.width, c.height);
  if (!mapVisible) return;
  const rooms = [...dungeon.rooms.values()], xs = rooms.map(r => r.x), ys = rooms.map(r => r.y);
  const cell = Math.min(28, (c.width - 24) / (Math.max(...xs) - Math.min(...xs) + 1), (c.height - 20) / (Math.max(...ys) - Math.min(...ys) + 1));
  const ox = (c.width - (Math.max(...xs) - Math.min(...xs) + 1) * cell) / 2;
  const oy = (c.height - (Math.max(...ys) - Math.min(...ys) + 1) * cell) / 2;
  for (const room of rooms) {
    if (!room.discovered) continue;
    const x = ox + (room.x - Math.min(...xs)) * cell, y = oy + (room.y - Math.min(...ys)) * cell;
    for (const d of ['N','S','E','W']) if (room.doors[d]) {
      ctx.strokeStyle = 'rgba(201,164,92,.42)'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(x + cell/2, y + cell/2); ctx.lineTo(x + cell/2 + DIRS[d].dx * cell, y + cell/2 + DIRS[d].dy * cell); ctx.stroke();
    }
    ctx.fillStyle = room === currentRoom ? '#e8dfca' : room.type === 'boss' ? '#c54840' : room.type === 'treasure' ? '#d9b866' : '#655d52';
    ctx.fillRect(x + 5, y + 4, cell - 10, cell - 8);
    if (room === currentRoom) { ctx.strokeStyle = '#fff3d4'; ctx.lineWidth = 1; ctx.strokeRect(x + 3.5, y + 2.5, cell - 7, cell - 5); }
  }
}

