179:       if (r === start) continue;
180:       const adjacent = DIR_NAMES.filter(dn => this.rooms.has(key(r.x + DIRS[dn].dx, r.y + DIRS[dn].dy)));
181:       const dd = dist.get(key(r.x, r.y)) || 0;
182:       if (adjacent.length <= 1 && dd > bossDist) { bossDist = dd; bossRoom = r; }
