113: export class Dungeon {
114:   constructor(seed = Math.floor(Math.random() * 1e9)) {
115:     this.seed = seed;
116:     this.floorIndex = 0;
117:     this.rooms = new Map();
118:     this.start = null;
119:   }
120: 
121:   rng(offset = 0) {
122:     let a = (this.seed + this.floorIndex * 7717 + offset) >>> 0;
123:     return () => {
124:       a |= 0; a = (a + 0x6D2B79F5) | 0;
125:       let t = Math.imul(a ^ (a >>> 15), 1 | a);
126:       t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
127:       return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
128:     };
129:   }
