133:   generateFloor(floorIndex) {
134:     this.floorIndex = floorIndex;
135:     this.rooms = new Map();
136:     const rand = this.rng(3);
137:     const target = 8 + floorIndex;
138:     const addRoom = (x, y, type = 'normal') => {
139:       const r = {
140:         x, y, type, seed: Math.floor(rand() * 100000),
141:         visited: false, cleared: type === 'start',
142:         doors: { N: false, E: false, S: false, W: false },
143:         discovered: false,
144:         entered: false
145:       };
146:       this.rooms.set(key(x, y), r);
147:       return r;
148:     };
149:     const start = addRoom(0, 0, 'start');
150:     this.start = start;
151:     let attempts = 0;
152:     while (this.rooms.size < target && attempts < 600) {
153:       attempts++;
154:       const list = [...this.rooms.values()].filter(r => r.type !== 'boss' && r.type !== 'treasure');
155:       if (!list.length) break;
156:       const from = list[Math.floor(rand() * list.length)];
157:       const dirName = DIR_NAMES[Math.floor(rand() * 4)];
158:       const d = DIRS[dirName];
159:       const nx = from.x + d.dx, ny = from.y + d.dy;
160:       if (Math.abs(nx) > 5 || Math.abs(ny) > 5) continue;
161:       if (this.rooms.has(key(nx, ny))) continue;
162:       addRoom(nx, ny);
163:     }
164: 
165:     // A couple of loops make the map less like a pure corridor.
166:     const all = [...this.rooms.values()];
167:     for (let i = 0; i < 2; i++) {
168:       const a = all[Math.floor(rand() * all.length)];
169:       const dirName = DIR_NAMES[Math.floor(rand() * 4)];
170:       const b = this.rooms.get(key(a.x + DIRS[dirName].dx, a.y + DIRS[dirName].dy));
171:       if (b && a.type !== 'start' && b.type !== 'start' && (a.type === 'normal' || b.type === 'normal')) {
172:         // connections are derived from adjacency, so this already creates a loop
173:       }
174:     }
175: 
176:     const dist = this.bfs(start);
177:     let bossRoom = null, bossDist = -1;
178:     for (const r of this.rooms.values()) {
179:       if (r === start) continue;
180:       const adjacent = DIR_NAMES.filter(dn => this.rooms.has(key(r.x + DIRS[dn].dx, r.y + DIRS[dn].dy)));
181:       const dd = dist.get(key(r.x, r.y)) || 0;
182:       if (adjacent.length <= 1 && dd > bossDist) { bossDist = dd; bossRoom = r; }
183:     }
184:     if (!bossRoom) bossRoom = all[all.length - 1];
185:     bossRoom.type = 'boss';
186:     bossRoom.cleared = false;
187: 
188:     let treasure = null, treasureDist = -1;
189:     for (const r of this.rooms.values()) {
190:       if (r === start || r === bossRoom) continue;
191:       const adjacent = DIR_NAMES.filter(dn => this.rooms.has(key(r.x + DIRS[dn].dx, r.y + DIRS[dn].dy)));
192:       const dd = dist.get(key(r.x, r.y)) || 0;
193:       if (adjacent.length <= 1 && dd > treasureDist) { treasureDist = dd; treasure = r; }
194:     }
195:     if (!treasure) treasure = all.find(r => r !== start && r !== bossRoom);
196:     if (treasure) treasure.type = 'treasure';
197: 
198:     // Derive doors from adjacency.
199:     for (const r of this.rooms.values()) {
200:       for (const dn of DIR_NAMES) {
201:         const d = DIRS[dn];
202:         if (this.rooms.has(key(r.x + d.dx, r.y + d.dy))) r.doors[dn] = true;
203:       }
204:     }
205: 
206:     // Entrance room gets a warm safe-room feel; everything is pre-lit by theme.
207:     start.cleared = true;
208:     start.entered = true;
209:     start.visited = true;
210:     start.discovered = true;
211:     return start;
212:   }
