170:   createEnemy(type, theme, variant = 0) {
171:     const group = new THREE.Group();
172:     const body = new THREE.Group();
173:     group.add(body);
174:     const shadow = this.shadow(type === 'boss' ? 3.6 : type === 'fly' ? 0.55 : 0.9, 0.58);
175:     if (type === 'fly') shadow.position.y = 0.01;
176:     group.add(shadow);
177: 
178:     const colors = {
179:       gurgle: [0x7d8f5a, 0x8d6f56, 0x687c4d],
180:       fly: [0x5c4d45, 0x4d4853, 0x3c3a2f],
181:       spitter: [0x7d557b, 0x5f6b83, 0x865f4d]
182:     };
183:     const color = (colors[type] || colors.gurgle)[variant % 3];
184:     const flesh = new THREE.MeshStandardMaterial({ color, roughness: 0.72, flatShading: true });
185:     const dark = new THREE.MeshStandardMaterial({ color: 0x15110f, roughness: 0.9 });
186:     const wet = new THREE.MeshStandardMaterial({ color: 0x2a1a18, roughness: 0.25, metalness: 0.1 });
187:     const eyeWhite = new THREE.MeshBasicMaterial({ color: 0xf2e7cf });
188:     const pupil = new THREE.MeshBasicMaterial({ color: 0x0a0605 });
189:     const accent = new THREE.MeshStandardMaterial({
190:       color: type === 'spitter' ? 0xc5a44c : 0xa54832,
191:       roughness: 0.4, emissive: type === 'spitter' ? 0x3a2b05 : 0x1d0404
192:     });
193: 
194:     if (type === 'gurgle') {
195:       const torso = G(this.sphereLow, flesh);
196:       torso.scale.set(0.48, 0.44, 0.42);
197:       torso.position.y = 0.47;
198:       body.add(torso);
199:       // lumpy back
200:       for (let i = 0; i < 3; i++) {
201:         const lump = G(this.sphereLow, flesh);
202:         const a = (i / 3) * Math.PI * 2;
203:         lump.scale.set(0.17, 0.16, 0.14);
204:         lump.position.set(Math.cos(a) * 0.3, 0.68 + (i % 2) * 0.13, Math.sin(a) * 0.24);
205:         body.add(lump);
206:       }
207:       // eyes
208:       for (const side of [-1, 1]) {
209:         const eye = G(this.sphereLow, eyeWhite);
210:         eye.scale.set(0.1, 0.13, 0.06);
211:         eye.position.set(side * 0.17, 0.54, 0.37);
212:         body.add(eye);
213:         const p = G(this.sphereLow, pupil);
214:         p.scale.set(0.045, 0.06, 0.025);
215:         p.position.set(side * 0.17, 0.54, 0.42);
216:         body.add(p);
217:       }
218:       // mouth
219:       const mouth = G(this.sphereLow, wet);
220:       mouth.scale.set(0.19, 0.07, 0.03);
221:       mouth.position.set(0, 0.34, 0.39);
222:       body.add(mouth);
223:       // feet
224:       for (const side of [-1, 1]) {
225:         const foot = G(this.sphereLow, flesh);
226:         foot.scale.set(0.16, 0.07, 0.18);
227:         foot.position.set(side * 0.2, 0.08, 0.03);
228:         body.add(foot);
229:       }
230:       group.userData = { body, torso, speed: 2.0 + Math.random() * 0.3 };
231:     } else if (type === 'fly') {
232:       const torso = G(this.sphereLow, flesh);
233:       torso.scale.set(0.27, 0.25, 0.25);
234:       torso.position.y = 0.95;
235:       body.add(torso);
236:       for (const side of [-1, 1]) {
237:         const eye = G(this.sphereLow, eyeWhite);
238:         eye.scale.set(0.1, 0.12, 0.08);
239:         eye.position.set(side * 0.11, 0.99, 0.2);
240:         body.add(eye);
241:         const p = G(this.sphereLow, pupil);
242:         p.scale.set(0.045, 0.06, 0.03);
243:         p.position.set(side * 0.11, 0.99, 0.27);
244:         body.add(p);
245:       }
246:       const wings = [];
247:       for (const side of [-1, 1]) {
248:         const wingPivot = new THREE.Group();
249:         wingPivot.position.set(side * 0.15, 1.05, -0.05);
250:         const wing = G(new THREE.PlaneGeometry(0.55, 0.32), new THREE.MeshBasicMaterial({
251:           color: 0xd9d4c0, transparent: true, opacity: 0.38, side: THREE.DoubleSide, depthWrite: false
252:         }));
253:         wing.rotation.x = -Math.PI / 2;
254:         wing.rotation.z = side * 0.25;
255:         wing.position.x = side * 0.26;
256:         wingPivot.add(wing);
257:         body.add(wingPivot);
258:         wings.push(wingPivot);
259:       }
260:       // little dangling legs
261:       for (let i = 0; i < 3; i++) {
262:         const leg = G(this.cyl, dark);
263:         leg.scale.set(0.012, 0.17, 0.012);
264:         leg.position.set((i - 1) * 0.08, 0.8, -0.03);
265:         leg.rotation.z = (i - 1) * 0.15;
266:         body.add(leg);
267:       }
268:       group.userData = { body, torso, wings, speed: 2.6 + Math.random() * 0.5 };
269:     } else if (type === 'spitter') {
270:       const torso = G(this.sphereLow, flesh);
271:       torso.scale.set(0.42, 0.5, 0.38);
272:       torso.position.y = 0.58;
273:       body.add(torso);
274:       // spikes
275:       for (let i = 0; i < 7; i++) {
276:         const a = (i / 7) * Math.PI * 2;
277:         const spike = G(new THREE.ConeGeometry(0.1, 0.35, 5), accent);
278:         spike.position.set(Math.cos(a) * 0.4, 0.62 + (i % 3) * 0.09, Math.sin(a) * 0.36);
279:         spike.rotation.z = -Math.cos(a) * 0.7;
280:         spike.rotation.x = Math.sin(a) * 0.7;
281:         body.add(spike);
282:       }
283:       // big single eye
284:       const eye = G(this.sphereLow, eyeWhite);
285:       eye.scale.set(0.19, 0.21, 0.1);
286:       eye.position.set(0, 0.68, 0.34);
287:       body.add(eye);
288:       const p = G(this.sphereLow, pupil);
289:       p.scale.set(0.08, 0.11, 0.04);
290:       p.position.set(0, 0.68, 0.43);
291:       body.add(p);
292:       const mouth = G(this.sphereLow, wet);
293:       mouth.scale.set(0.12, 0.13, 0.05);
294:       mouth.position.set(0, 0.39, 0.35);
295:       body.add(mouth);
296:       // feet
297:       for (const side of [-1, 1]) {
298:         const foot = G(this.sphereLow, flesh);
299:         foot.scale.set(0.14, 0.08, 0.16);
300:         foot.position.set(side * 0.18, 0.08, 0);
301:         body.add(foot);
302:       }
303:       group.userData = { body, torso, speed: 1.65 + Math.random() * 0.2 };
304:     } else if (type === 'boss') {
305:       const themeColor = new THREE.Color(theme.bossColor || 0xb98778);
306:       const bossFlesh = new THREE.MeshStandardMaterial({ color: themeColor, roughness: 0.62, flatShading: true });
307:       const bossDark = new THREE.MeshStandardMaterial({ color: 0x3a1214, roughness: 0.45 });
308:       const teeth = new THREE.MeshStandardMaterial({ color: 0xe6d9b0, roughness: 0.5 });
309:       const bossGlow = new THREE.MeshBasicMaterial({ color: theme.bossGlow || 0xff5538 });
310: 
311:       const head = new THREE.Group();
312:       head.position.y = 1.9;
313:       body.add(head);
314:       const skull = G(this.sphere, bossFlesh);
315:       skull.scale.set(1.42, 1.32, 1.28);
316:       head.add(skull);
317:       // eye sockets
318:       for (const side of [-1, 1]) {
319:         const socket = G(this.sphereLow, bossDark);
320:         socket.scale.set(0.32, 0.24, 0.15);
321:         socket.position.set(side * 0.5, 0.34, 1.12);
322:         head.add(socket);
323:         const glow = G(this.sphereLow, bossGlow);
324:         glow.scale.set(0.14, 0.12, 0.05);
325:         glow.position.set(side * 0.5, 0.34, 1.24);
326:         head.add(glow);
327:       }
328:       // giant mouth
329:       const mouth = G(this.sphereLow, bossDark);
330:       mouth.scale.set(0.62, 0.44, 0.12);
331:       mouth.position.set(0, -0.28, 1.15);
332:       head.add(mouth);
333:       // teeth ring
334:       for (let i = 0; i < 12; i++) {
335:         const a = (i / 12) * Math.PI * 2;
336:         const tooth = G(new THREE.ConeGeometry(0.09, 0.24, 5), teeth);
337:         tooth.position.set(Math.cos(a) * 0.5, -0.28 + Math.sin(a) * 0.33, 1.25);
338:         tooth.rotation.z = -a + Math.PI / 2;
339:         head.add(tooth);
340:       }
341:       // crown horns
342:       for (let i = 0; i < 6; i++) {
343:         const a = (i / 6) * Math.PI * 2 + 0.3;
344:         const horn = G(new THREE.ConeGeometry(0.14, 0.65, 6), bossDark);
345:         horn.position.set(Math.cos(a) * 1.02, 1.12, Math.sin(a) * 0.8);
346:         horn.rotation.z = -Math.cos(a) * 0.5;
347:         horn.rotation.x = Math.sin(a) * 0.5;
348:         head.add(horn);
349:       }
350:       // floating hands
351:       const hands = [];
352:       for (const side of [-1, 1]) {
353:         const hand = new THREE.Group();
354:         const palm = G(this.sphereLow, bossFlesh);
355:         palm.scale.set(0.33, 0.25, 0.2);
356:         hand.add(palm);
357:         for (let f = 0; f < 3; f++) {
358:           const finger = G(this.cyl, bossDark);
359:           finger.scale.set(0.035, 0.35, 0.035);
360:           finger.position.set((f - 1) * 0.15, -0.32, 0.03);
361:           finger.rotation.z = (f - 1) * 0.16;
362:           hand.add(finger);
363:         }
364:         hand.position.set(side * 1.85, 1.7, 0.25);
365:         body.add(hand);
366:         hands.push(hand);
367:       }
368:       const light = new THREE.PointLight(theme.bossGlow || 0xff5538, 2.2, 7, 2);
369:       light.position.set(0, 2.1, 1.4);
370:       group.add(light);
371:       group.userData = { body, head, hands, speed: 1.35, bossFlesh };
372:     }
373:     return group;
374:   }
