337:         tooth.position.set(Math.cos(a) * 0.5, -0.28 + Math.sin(a) * 0.33, 1.25);
338:         tooth.rotation.z = -a + Math.PI / 2;
339:         head.add(tooth);
340:       }
341:       // crown horns
342:       for (let i = 0; i < 6; i++) {
343:         const a = (i / 6) * Math.PI * 2 + 0.3;
344:         const horn = G(new THREE.ConeGeometry(0.14, 0.65, 6), bossDark);
345:         horn.position.set(Math.cos(a) * 1.02, 1.12, Math.sin(a) * 0.8);
