611:   createRock(seed = 1, theme = {}) {
612:     const rand = (s => () => (s = Math.sin(s) * 10000, s - Math.floor(s)))(seed);
613:     const group = new THREE.Group();
614:     const mat = new THREE.MeshStandardMaterial({
615:       color: theme.rockColor || 0x554d45, roughness: 0.98, flatShading: true
616:     });
617:     const geo = new THREE.DodecahedronGeometry(0.62, 0);
618:     const pos = geo.attributes.position;
619:     for (let i = 0; i < pos.count; i++) {
620:       pos.setXYZ(i,
621:         pos.getX(i) * (0.82 + rand() * 0.35),
622:         pos.getY(i) * (0.72 + rand() * 0.3),
623:         pos.getZ(i) * (0.82 + rand() * 0.35));
624:     }
625:     geo.computeVertexNormals();
626:     const rock = G(geo, mat);
627:     rock.position.y = 0.52;
628:     rock.rotation.y = rand() * 6;
629:     group.add(rock);
630:     const rock2 = G(new THREE.DodecahedronGeometry(0.32, 0), mat);
631:     rock2.position.set(0.38, 0.26, 0.24);
632:     rock2.rotation.set(rand(), rand(), rand());
633:     group.add(rock2);
634:     const shadow = this.shadow(1.4, 0.5);
635:     group.add(shadow);
636:     group.userData = { mesh: rock, radius: 0.62, type: 'rock' };
637:     return group;
638:   }
