382:   if (!collideAt(player.x, nz)) player.z = clamp(nz, -boundZ, boundZ);
383:   if (mx || mz) {
384:     playerMesh.userData.legs?.forEach((leg, i) => { leg.rotation.x = Math.sin(runTime * 12 + i * Math.PI) * 0.42; });
385:     stepTimer -= dt;
386:     if (stepTimer <= 0) { audio.step(); stepTimer = 0.34; }
387:   } else playerMesh.userData.legs?.forEach(leg => { leg.rotation.x *= 0.75; });
388:   playerMesh.position.set(player.x, player.invuln > 0 && Math.floor(runTime * 16) % 2 ? 0.14 : 0, player.z);
