417:       vx = dx / dist * e.speed * target; vz = dz / dist * e.speed * target;
418:       e.mesh.position.y = 0.18 + Math.sin(e.phase * 7) * 0.18;
419:     } else if (e.type === 'spitter' && dist > 4.5) {
420:       vx = dx / dist * e.speed * 0.55; vz = dz / dist * e.speed * 0.55;
421:     } else if (e.type !== 'spitter' || dist < 3.2) {
422:       vx = dx / dist * e.speed; vz = dz / dist * e.speed;
