(async () => {
  const browser = await chromium.launch({ headless: true, timeout: 15000, args: ['--no-sandbox', '--disable-gpu', '--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--disable-dev-shm-usage'] });
  try {
