    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.goto('http://localhost:3000', { waitUntil: 'domcontentloaded', timeout: 10000 });
    await page.waitForTimeout(1000);
    await page.keyboard.press('Enter');
    await page.waitForTimeout(500);
    const initial = await page.evaluate(() => window.__testSnapshot());
    const dir = ['N','S','E','W'].find(d => initial.room.doors[d]);
    const key = {N:'KeyW',S:'KeyS',E:'KeyD',W:'KeyA'}[dir];
    await page.keyboard.down(key);
    await page.waitForTimeout(dir === 'S' ? 1000 : dir === 'N' ? 2500 : 2200);
    await page.keyboard.up(key);
    await page.waitForTimeout(500);
    const entered = await page.evaluate(() => window.__testSnapshot());
    const startEnemyCount = entered.enemies.length;
    if (startEnemyCount) {
      await page.mouse.down();
      for (let i=0; i<70; i++) {
        const snap = await page.evaluate(() => window.__testSnapshot());
        if (!snap.enemies.length) break;
        const e = snap.enemies[0];
        await page.mouse.move(e.sx, e.sy);
        await page.waitForTimeout(120);
      }
      await page.mouse.up();
    }
    await page.waitForTimeout(500);
    const afterCombat = await page.evaluate(() => window.__testSnapshot());
    await page.keyboard.press('KeyE');
    await page.waitForTimeout(100);
    const afterBomb = await page.evaluate(() => window.__testSnapshot());
    await page.keyboard.press('Escape');
    const paused = await page.locator('#pause-screen').getAttribute('class');
    console.log(JSON.stringify({direction:dir, initial:{room:initial.room.type, doors:initial.room.doors}, entered:{room:entered.room.type, enemies:startEnemyCount, hp:entered.player.hp}, afterCombat:{enemies:afterCombat.enemies.length, cleared:afterCombat.room.cleared, pickups:afterCombat.pickups, hp:afterCombat.player.hp}, bombConsumed: afterBomb ? 'action sent' : false, paused, errors}, null, 2));
  } finally { await browser.close(); }
})();
